package com.volna.profile_service.exception;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.time.LocalDateTime;import java.util.*;@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(ResourceNotFoundException.class)ResponseEntity<?>nf(ResourceNotFoundException x){return ResponseEntity.status(404).body(Map.of("timestamp",LocalDateTime.now(),"status",404,"error","Not Found","message",x.getMessage()));}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<?>v(MethodArgumentNotValidException e){Map<String,String>m=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->m.put(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(Map.of("timestamp",LocalDateTime.now(),"status",400,"error","Validation Failed","messages",m));}@ExceptionHandler(Exception.class)ResponseEntity<?>e(Exception x){return ResponseEntity.status(500).body(Map.of("timestamp",LocalDateTime.now(),"status",500,"error","Internal Server Error","message",x.getMessage()));}}
